  ('3401 Series Set-Screw Round Belt Pulley (5mm Bore, 16mm PD)', '3401-0005-0016', null, 'goBILDA', null, true, 'https://www.gobilda.com/3401-series-set-screw-round-belt-pulley-5mm-bore-16mm-pd/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/563/images/3494/3401-0005-0016__45648__47288.1701991916.386.513.jpg?c=1', 'MOTION / Round Belts & Pulleys / Set Screw Round Belt Pulleys', 'gobilda'),
  ('3401 Series Set-Screw Round Belt Pulley (6mm Bore, 8mm PD)', '3401-0006-0008', 'This 6mm bore pulley fastens to a 6mm round or 6mm D-shaft via its M5 set-screw so that it can drive a round belt. Round belts are excellent for low-torque applications. Since the belt stretches, close is good enough when it comes to calculating what belt length you need between two pulleys. This method of power transmission is also extremely quiet!', 'goBILDA', null, true, 'https://www.gobilda.com/3401-series-set-screw-round-belt-pulley-6mm-bore-8mm-pd/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/564/images/3503/3401-0006-0008_new__33833__23101.1701991918.386.513.jpg?c=1', 'MOTION / Round Belts & Pulleys / Set Screw Round Belt Pulleys', 'gobilda'),
  ('3401 Series Set-Screw Round Belt Pulley (6mm Bore, 16mm PD)', '3401-0006-0016', null, 'goBILDA', null, true, 'https://www.gobilda.com/3401-series-set-screw-round-belt-pulley-6mm-bore-16mm-pd/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/565/images/3511/3401-0006-0016__66442__60546.1701991920.386.513.jpg?c=1', 'MOTION / Round Belts & Pulleys / Set Screw Round Belt Pulleys', 'gobilda'),
  ('3401 Series Set-Screw Round Belt Pulley (8mm REX® Bore, 16mm PD)', '3401-4008-0016', 'This 16mm PD, 8mm REX® pulley can achieve positive drive on 8mm REX™ profile shafting to drive a round belt. The two M5 set-screws provide a secure connection to the shaft. Round belts are excellent for low-torque applications. Since the belt stretches, close is good enough when it comes to calculating what belt length you need between two pulleys. This method of power transmission is also extremely quiet!', 'goBILDA', null, true, 'https://www.gobilda.com/3401-series-set-screw-round-belt-pulley-8mm-rex-bore-16mm-pd/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2019/images/11065/3401-4008-0016__53145__36070.1701994303.386.513.jpg?c=1', 'MOTION / Round Belts & Pulleys / Set Screw Round Belt Pulleys', 'gobilda'),
  ('3402 Series 3mm HTD Pitch Plastic Hub Mount Timing Belt Pulley (14mm Bore, 36 Tooth)', '3402-0014-0036', 'This hub mount pulley has a small enough diameter that it will run inside channel and other structural components with 43mm of space. The two-piece construction nests together seamlessly and holds together with screws that pass through the thru-holes into a hub or threaded component on the 16mm pattern.', 'goBILDA', null, true, 'https://www.gobilda.com/3402-series-3mm-htd-pitch-plastic-hub-mount-timing-belt-pulley-14mm-bore-36-tooth/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/567/images/3527/3402-0014-0036__93190__49505.1701991924.386.513.jpg?c=1', null, 'gobilda'),
  ('3402 Series 3mm HTD Pitch Plastic Hub Mount Timing Belt Pulley (14mm Bore, 72 Tooth)', '3402-0014-0072', 'This 72 tooth timing pulley is a two piece pulley that nests together and fastens to the other half with M4 button head screws. The diameter allows for the full pattern to be molded into the face so that you can fasten to the standard 16mm pattern or the larger 32mm pattern. Comes preassembled with M4 screws and nuts as shown in image 1.', 'goBILDA', null, true, 'https://www.gobilda.com/3402-series-3mm-htd-pitch-plastic-hub-mount-timing-belt-pulley-14mm-bore-72-tooth/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1154/images/5773/3402-0014-0072__10348__79574.1701992642.386.513.jpg?c=1', null, 'gobilda'),
  ('3402 Series 3mm HTD Pitch Plastic Hub Mount Timing Belt Pulley (14mm Bore, 108 Tooth)', '3402-0014-0108', 'This 108 tooth timing pulley is a two piece pulley that nests together and fastens to the other half with M4 button head screws. The diameter allows for the full pattern to be molded into the face so that you can fasten to the standard 16mm pattern or the larger 32mm pattern. Comes preassembled with M4 screws and nuts as shown in image 1.', 'goBILDA', null, true, 'https://www.gobilda.com/3402-series-3mm-htd-pitch-plastic-hub-mount-timing-belt-pulley-14mm-bore-108-tooth/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1161/images/5809/3402-0014-0108__89559__94079.1701992653.386.513.jpg?c=1', null, 'gobilda'),
