  ('3501 Series Lead Screw (8mm Lead, 4 Start, 950mm Length)', '3501-0804-0950', null, 'goBILDA', null, true, 'https://www.gobilda.com/3501-series-lead-screw-8mm-lead-4-start-950mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/568/images/3535/3501-0804-0950__59004__58782.1701991927.386.513.jpg?c=1', 'MOTION / Lead Screws / 8mm Lead Screws', 'gobilda'),
  ('3501 Series Lead Screw (8mm Lead, 4 Start, 1250mm Length)', '3501-0804-1250', null, 'goBILDA', null, true, 'https://www.gobilda.com/3501-series-lead-screw-8mm-lead-4-start-1250mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/570/images/3545/3501-0804-1250__57303__28106.1701991930.386.513.jpg?c=1', 'MOTION / Lead Screws / 8mm Lead Screws', 'gobilda'),
  ('3503 Series Lead Screw Nut for Open goRAIL® (8mm Lead, 4 Start, 38mm Length)', '3503-0804-0038', 'The unique shape of this lead screw nut allows it to index with the bore of Open goRAIL ® to create a linear drive with all kinds of possibilities. The 8mm lead screw bore is 19mm long for excellent durability in high stress applications. The remaining 19mm bore is clearanced so the lead screw can pass through without creating unnecessary friction. The threaded holes on the ends can be used to attach smaller components such as a limit switch contact. The five threaded holes on the top of the…', 'goBILDA', null, true, 'https://www.gobilda.com/3503-series-lead-screw-nut-for-open-gorail-8mm-lead-4-start-38mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/571/images/3554/3503-0004-0038__08941__32657.1701991933.386.513.jpg?c=1', 'STRUCTURE / goRAIL® / goRAIL® Accessories', 'gobilda'),
  ('3504 Series Lead Screw Clamping Collar (8mm Lead, 4 Start, 18mm OD, 8mm Length)', '3504-0804-1808', 'This product has been discontinued. It has been replaced by the 3504-0804-2109. This lead screw collar provides a way to hold an 8mm lead screw in place axially. The bore precisely matches the 8mm lead screw in order to create maximum contact area.', 'goBILDA', null, true, 'https://www.gobilda.com/3504-series-lead-screw-clamping-collar-8mm-lead-4-start-18mm-od-8mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/572/images/3562/3504-0804-1808__42647__62281.1701991937.386.513.jpg?c=1', null, 'gobilda'),
  ('3504 Series Lead Screw Clamping Collar (8mm Lead, 4 Start, 21mm OD, 9mm Length)', '3504-0804-2109', 'This lead screw collar provides a way to hold an 8mm lead screw in place axially. The bore precisely matches the 8mm lead screw in order to create maximum contact area.', 'goBILDA', null, true, 'https://www.gobilda.com/3504-series-lead-screw-clamping-collar-8mm-lead-4-start-21mm-od-9mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1422/images/7047/3504-0804-2109__22468__98720.1701993047.386.513.png?c=1', 'MOTION / Collars', 'gobilda'),
  ('3505 Series Lead Screw Pattern Nut (8mm Lead, 4 Start, 32mm OD, 16mm Length)', '3505-0804-3216', 'The pattern on this lead screw nut allows you to fasten it to a part which possesses the 16mm pattern - whether thru-hole or threaded. The 32mm OD also allows it to be mated with 32mm clamping components.', 'goBILDA', null, true, 'https://www.gobilda.com/3505-series-lead-screw-pattern-nut-8mm-lead-4-start-32mm-od-16mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/575/images/3574/ang1__26574__33129.1701991941.386.513.jpg?c=1', 'MOTION / Lead Screws / 8mm Lead Screw Nuts', 'gobilda'),
  ('3506 Series Lead Screw Square Nut (8mm Lead, 4 Start, 16mm Length)', '3506-0804-0016', 'This specialized nut is intended to index inside the square bore of goRAIL® or goTUBE in order to create linear motion as the 8mm lead screw is rotated. The M12 threads offer an attachment point for the 4101 Series Threaded Tube. The slight recesses at the base provide a spot to install magnets.', 'goBILDA', null, true, 'https://www.gobilda.com/3506-series-lead-screw-square-nut-8mm-lead-4-start-16mm-length/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/577/images/3580/3506-0804-0016__72227__36906.1701991942.386.513.jpg?c=1', 'STRUCTURE / goRAIL® / goRAIL® Accessories', 'gobilda'),
  ('3508 Series Lead Screw Nut for V-Guide (8mm Lead, 4 Start, 14mm Width, 32mm Height)', '3508-0804-1432', 'This specialized nut is for creating linear motion with v-guide and 1120 Series U-Channel. The threaded holes in the sides allow the Angle Mount (1-1) to fasten which will provide a location for v-groove bearings.', 'goBILDA', null, true, 'https://www.gobilda.com/3508-series-lead-screw-nut-for-v-guide-8mm-lead-4-start-14mm-width-32mm-height/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/579/images/3586/3508-0804-1432__46539__72028.1701991945.386.513.jpg?c=1', 'MOTION / Lead Screws / 8mm Lead Screw Nuts', 'gobilda'),
  ('3600 Series V-Wheel (5mm Bore, 10mm OD, 10mm Width) - 2 Pack', '3600-0005-1010', 'These V-Wheels have chamfered edges that allow them to run down the V-groove of goRAIL®. The V-Wheels are an excellent support mechanism for a super smooth linear motion setup.', 'goBILDA', null, true, 'https://www.gobilda.com/3600-series-v-wheel-5mm-bore-10mm-od-10mm-width-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/581/images/3592/3600-0005-1010__70926__91413.1701991946.386.513.jpg?c=1', 'MOTION / Wheels & Tires / V-Wheels', 'gobilda'),
  ('3600 Series W-Wheel (6mm Bore, 29mm OD, 10mm Width) - 2 Pack', '3600-0006-2910', 'W-Wheels are purpose built for two primary applications. The outside edge has a 45 degree chamfer to align with the inside groove of goRAIL®. The inside of the wheel has a V-groove to align on V-Guides, but will work on any square edge given the wheel is held at the proper angle.', 'goBILDA', null, true, 'https://www.gobilda.com/3600-series-w-wheel-6mm-bore-29mm-od-10mm-width-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/573/images/3561/3600-0006-2910__24530__76318.1701991936.386.513.jpg?c=1', 'MOTION / Linear Motion Guides / V-Guide Based', 'gobilda'),
  ('3601 Series Rhino Wheel (14mm Bore, 72mm Diameter)', '3601-0014-0072', 'These wheels have an overall diameter of 72mm and a width of 32mm. The offset center gives you 8mm from mounting surface to edge on one(14) side and 16mm on the other which allows you to change your track-width by flipping the wheel. The 14mm bore provides a centering mechanism on hubs that have a 14mm protrusion.', 'goBILDA', null, true, 'https://www.gobilda.com/3601-series-rhino-wheel-14mm-bore-72mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/574/images/3564/3601-0014-0072__19858__72064.1701991938.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Rhino Wheels', 'gobilda'),
  ('3601 Series Rhino Wheel (14mm Bore, 96mm Diameter)', '3601-0014-0096', 'These wheels have an overall diameter of 96mm and a width of 32mm. The offset center gives you 8mm from mounting surface to edge on one(15) side and 16mm on the other which allows you to change your track-width by flipping the wheel. The 14mm bore provides a centering mechanism on hubs that have a 14mm protrusion.', 'goBILDA', null, true, 'https://www.gobilda.com/3601-series-rhino-wheel-14mm-bore-96mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/576/images/3578/3601-0014-0096__46487__59578.1701991942.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Rhino Wheels', 'gobilda'),
  ('3601 Series Rhino Wheel (14mm Bore, 120mm Diameter)', '3601-0014-0120', 'These wheels have an overall diameter of 120mm and a width of 32mm. The offset center gives you 8mm from mounting surface to edge on one(16) side and 16mm on the other which allows you to change your track-width by flipping the wheel. The 14mm bore provides a centering mechanism on hubs that have a 14mm protrusion.', 'goBILDA', null, true, 'https://www.gobilda.com/3601-series-rhino-wheel-14mm-bore-120mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/578/images/3585/3601-0014-0120__03646__47818.1701991944.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Rhino Wheels', 'gobilda'),
  ('3601 Series Rhino Wheel (32mm Bore, 96mm Diameter)', '3601-0032-0096', 'These wheels have an overall diameter of 96mm and a width of 32mm. The offset center gives you 8mm from mounting surface to edge on one(17) side and 16mm on the other which allows you to change your track-width by flipping the wheel.', 'goBILDA', null, true, 'https://www.gobilda.com/3601-series-rhino-wheel-32mm-bore-96mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/580/images/3590/3601-0032-0096__29965__86065.1701991946.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Rhino Wheels', 'gobilda'),
  ('3601 Series Rhino Wheel (32mm Bore, 120mm Diameter)', '3601-0032-0120', 'These wheels have an overall diameter of 120mm and a width of 32mm. The offset center gives you 8mm from mounting surface to edge on one(18) side and 16mm on the other which allows you to change your track-width by flipping the wheel.', 'goBILDA', null, true, 'https://www.gobilda.com/3601-series-rhino-wheel-32mm-bore-120mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/583/images/3601/3601-0032-0120__47982__57399.1701991950.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Rhino Wheels', 'gobilda'),
  ('3604 Series Omni Wheel (14mm Bore, 72mm Diameter)', '3604-0014-0072', null, 'goBILDA', null, true, 'https://www.gobilda.com/3604-series-omni-wheel-14mm-bore-72mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/585/images/3609/3604-0014-0072__18802__00374.1701991952.386.513.jpg?c=1', null, 'gobilda'),
  ('3604 Series Omni Wheel (14mm Bore, 96mm Diameter)', '3604-0014-0096', null, 'goBILDA', null, true, 'https://www.gobilda.com/3604-series-omni-wheel-14mm-bore-96mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/587/images/3617/3604-0014-0096__80434__67170.1701991954.386.513.jpg?c=1', null, 'gobilda'),
  ('3604 Series Omni Wheel (14mm Bore, 120mm Diameter)', '3604-0014-0120', null, 'goBILDA', null, true, 'https://www.gobilda.com/3604-series-omni-wheel-14mm-bore-120mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/589/images/3625/3604-0014-0120__85748__40415.1701991956.386.513.jpg?c=1', null, 'gobilda'),
  ('3605 Series Hurricane Rim - 2 Pack', '3605-0014-0056', 'Hurricane Rims are the proper size to mount any of the Terrain Tires. Within the R/C car market, these are commonly referred to as 2.2 Rims as they have a 2.2" diameter. The center of the Hurricane Rim has the goBILDA 16mm pattern in order to mate to any of the 16mm pattern hubs. The offset center allows you to flip the wheel to quickly change the track-width of your robot. The Hurricane Rims have a ''bead'' for the tire to rest in, but it''s recommended you use CA glue or super glue to bond the…', 'goBILDA', null, true, 'https://www.gobilda.com/3605-series-hurricane-rim-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/591/images/3638/3605-0014-0056__64324__38172.1701991960.386.513.jpg?c=1', 'MOTION / Wheels & Tires / All-Terrain Wheels & Tires', 'gobilda'),
  ('3606 Series Mecanum Wheel (Left Slant, Bearing Supported Rollers, 100mm Diameter)', '3606-0000-0100', 'The Left Slant Mecanum is the same wheel you''ll find in the goBILDA Mecanum Wheel Set (which comes with two Left Slant Wheels and two Right Slant Wheels), but sold as a single wheel for whatever your needs demand. Since like-wheels are positioned catty-corner from one(19)-another on a conventional mecanum chassis, we decided to stray from calling this a left wheel or a right wheel. We named it based on the direction the leading edge of the roller faces, when installed and looking down on the…', 'goBILDA', null, true, 'https://www.gobilda.com/3606-series-mecanum-wheel-left-slant-bearing-supported-rollers-100mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1232/images/6135/3606-0000-0100__19001__30505.1701992760.386.513.jpg?c=1', null, 'gobilda'),
  ('3606 Series Mecanum Wheel (Right Slant, Bearing Supported Rollers, 100mm Diameter)', '3606-0100-0100', 'The Right Slant Mecanum is the same wheel you''ll find in the goBILDA Mecanum Wheel Set (which comes with two Left Slant Wheels and two Right Slant Wheels), but sold as a single wheel for whatever your needs demand. Since like-wheels are positioned catty-corner from one(20)-another on a conventional mecanum chassis we decided to stray from calling this a left wheel or a right wheel. We''ve named it based on the direction the leading edge of the roller faces, when installed and looking down on the…', 'goBILDA', null, true, 'https://www.gobilda.com/3606-series-mecanum-wheel-right-slant-bearing-supported-rollers-100mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1234/images/6147/3606-0100-0100__75249__06079.1701992764.386.513.jpg?c=1', null, 'gobilda'),
  ('3607 Series Disc Wheel (14mm Bore, 48mm Diameter, Black) - 2 Pack', '3607-0014-0048', null, 'goBILDA', null, true, 'https://www.gobilda.com/3607-series-disc-wheel-14mm-bore-48mm-diameter-black-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/582/images/3599/3607-0014-0048__10470__20300.1701991949.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Disc Wheels', 'gobilda'),
  ('3607 Series Disc Wheel (14mm Bore, 72mm Diameter, Black) - 2 Pack', '3607-0014-0072', null, 'goBILDA', null, true, 'https://www.gobilda.com/3607-series-disc-wheel-14mm-bore-72mm-diameter-black-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/584/images/3607/3607-0014-0072__54964__75412.1701991951.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Disc Wheels', 'gobilda'),
  ('3607 Series Disc Wheel (14mm Bore, 96mm Diameter, Black) - 2 Pack', '3607-0014-0096', null, 'goBILDA', null, true, 'https://www.gobilda.com/3607-series-disc-wheel-14mm-bore-96mm-diameter-black-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/586/images/3615/3607-0014-0096__75203__76490.1701991953.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Disc Wheels', 'gobilda'),
  ('3607 Series Disc Wheel (14mm Bore, 120mm Diameter, Black) - 2 Pack', '3607-0014-0120', null, 'goBILDA', null, true, 'https://www.gobilda.com/3607-series-disc-wheel-14mm-bore-120mm-diameter-black-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/588/images/3623/3607-0014-0120__28213__86854.1701991955.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Disc Wheels', 'gobilda'),
  ('3609 Series Leopard Tire - 2 Pack', '3609-0001-0001', 'Leopard Tires are gnarly! They''re constructed of a very pliable rubber to conform to the surface you''re driving over. The foam core of the tire is spongy in order to mimic a pneumatic tire running very low pressure for maximum traction in uneven terrain. The tread style is excellent for dirt, gravel and rock, but grips very well on hard terrain too.', 'goBILDA', null, true, 'https://www.gobilda.com/3609-series-leopard-tire-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/880/images/4768/3609-0001-0001__49966__02338.1701992293.386.513.jpg?c=1', null, 'gobilda'),
  ('3609 Series Cougar Tire - 2 Pack', '3609-0001-0002', 'Cougar Tires are ferocious! These tires are constructed of a very pliable rubber to conform to the surface you''re driving over. The foam core of the tire is spongy in order to mimic a pneumatic tire running very low pressure for maximum traction in uneven terrain. The open tread design is excellent for loose soil and mud, but grips well on hard terrain too.', 'goBILDA', null, true, 'https://www.gobilda.com/3609-series-cougar-tire-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/872/images/4746/3609-0001-0002__55649__28723.1701992287.386.513.jpg?c=1', null, 'gobilda'),
  ('Paddle Tire - 2 Pack', '3609-0001-0003', 'These paddle tires are ready to rip in a sand pit! They have a 55mm width for excellent flotation and straight line traction.', 'goBILDA', null, true, 'https://www.gobilda.com/paddle-tire-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/875/images/4752/3609-0001-0003__14645__72160.1701992289.386.513.jpg?c=1', 'MOTION / Wheels & Tires / All-Terrain Wheels & Tires', 'gobilda'),
  ('5.4" Truggy Tire (for 2.2" Rim, Includes Foam Insert) - 2 Pack', '3609-0001-0006', 'Whether you''re building a scale crawler to conquer Moabian terrain, or you''re scaling obstacles in your backyard, these tires are as ready for your project as they are to challenge the great outdoors! The tall profile and included foam inserts create a generous amount of pliability that allows the Truggy Tire to conform around terrain—just like an aired-down tire on a real trail-rig. Truggy Tires fit on 2.2" rims (like Hurricane Rims). Of course, if you''d like to put these shoes on your R/C…', 'goBILDA', null, true, 'https://www.gobilda.com/5-4-truggy-tire-for-2-2-rim-includes-foam-insert-2-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2369/images/14544/3609-0001-0006_Ang1__43734__96665.1741296060.386.513.jpg?c=1', 'MOTION / Wheels & Tires / All-Terrain Wheels & Tires', 'gobilda'),
  ('Mecanum Wheel Roller (White, 1-2) - 40 Pack', '3611-0001-0002', 'Note: These replacement rollers are only compatible with the 3213-3606-0001 mecanum wheels. Spice your robot up a bit with the ability to dye mecanum wheel rollers the color of your choice. The goBILDA Mecanum Wheels rock the goBILDA yellow rollers and look great doing so...but we have a slight bias. If yellow just doesn''t quite jive with your look, pop these white rollers into your concoction of dye and watch them take on a new look! Each pack contains 40 rollers - enough to swap out every…', 'goBILDA', null, true, 'https://www.gobilda.com/mecanum-wheel-roller-white-1-2-40-pack/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1281/images/6348/3611-0001-0002_02__73051__39012.1701992823.386.513.jpg?c=1', null, 'gobilda'),
  ('GripForce™ Mecanum Wheel Roller Pack (30A)', '3611-0030-0104', 'It''s been said that the last 10% toward completing a goal is always the "hardest." But when it comes to these 30A GripForce™ Rollers, that last bit of effort toward the goal of mecanum movement finesse is actually softer ! The baseline 40A rollers included out-of-the-box in GripForce™ Mecanum Wheels are perfectly balanced for grippiness and durability. Teams can rest assured that those rollers can endure years upon years of competition, without ever requiring a replacement! However, if you''d…', 'goBILDA', null, true, 'https://www.gobilda.com/gripforce-mecanum-wheel-roller-pack-30a/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2428/images/16727/30A-Pack-bin-not-included__05880.1779488042.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Mecanum Wheels', 'gobilda'),
  ('GripForce™ Mecanum Wheel Roller Pack (40A)', '3611-0040-0104', 'Ready to refresh your 40A rollers? While GripForce™ Mecanum Wheels are designed with extraordinary durability, rubber rollers are just as susceptible to the entropy of the Universe as anything else in existence, and can experience wear from long-term use. If your rollers are worn, or have been subject to an extreme event in which damage occurred, you can use this service pack to rebuild the rollers of your wheel while retaining its core and steel side plates. This pack contains 44 rollers,…', 'goBILDA', null, true, 'https://www.gobilda.com/gripforce-mecanum-wheel-roller-pack-40a/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2263/images/16726/40A-Pack-bin-not-included__34951.1779487848.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Mecanum Wheels', 'gobilda'),
  ('GripForce™ Mecanum Wheel Roller Pack (40A Durometer, 4 Rollers)', '3611-0140-0104', 'Don''t let an unexpected collision sideline your drivetrain. While GripForce™ Mecanum Wheels are engineered for durability, the intense nature of competition means rubber rollers can still experience wear over time or suffer sudden damage from an extreme on-field collision. Keeping a GripForce™ Roller Pack in your pit toolbox prepares you for on-the-fly maintenance, ensuring you can quickly rebuild your wheel''s rollers right on the workbench between matches. This pack contains everything you…', 'goBILDA', null, true, 'https://www.gobilda.com/gripforce-mecanum-wheel-roller-pack-40a-durometer-4-rollers/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2516/images/16718/d%25252F684%25252F40A_4pk__04642__66742.1779487121.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Mecanum Wheels', 'gobilda'),
  ('3612 Series Thin Rhino Wheel (14mm Bore, 96mm Diameter)', '3612-0014-0096', 'The 96mm wheel diameter matches many of our wheel options so you can mix-and-match at will. The slab-sided nature of the Thin Rhino Wheel can be mounted in either orientation - flip them out for a wide track-width or suck them in to minimize bump-steer on your Ackermann steering system. Bolt them together to build ''duals'' for greater traction and load-bearing capabilities.', 'goBILDA', null, true, 'https://www.gobilda.com/3612-series-thin-rhino-wheel-14mm-bore-96mm-diameter/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1433/images/7097/3612-0014-0096__44782__08684.1701993062.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Rhino Wheels', 'gobilda'),
  ('GripForce Gecko™ Wheel (14mm Bore, 72mm Diameter, 30A Durometer)', '3613-0014-0072', 'Grab the utmost of grippage with this 72mm Diameter Gripforce Gecko Wheel™! Constructed of high-grip silicone rubber, and featuring raised pips that echo the toe pads of a gecko, this wheel has excellent traction against a multitude of surfaces. The spoke design allows it to easily compress and conform around objects, and it''s non-directional: it will reliably provide the same results rotation after rotation, no matter what direction you spin it! The plastic center core features a 14mm bore…', 'goBILDA', null, true, 'https://www.gobilda.com/gripforce-gecko-wheel-14mm-bore-72mm-diameter-30a-durometer/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1379/images/15725/3613-0014-0072_REV2_-_CAT__98643.1767737240.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Intake Wheels', 'gobilda'),
  ('GripForce Gecko™ Wheel (14mm Bore, 96mm Diameter, 30A Durometer)', '3613-0014-0096', 'Grab the utmost of grippage with this 96mm Diameter Gripforce Gecko Wheel™! Constructed of high-grip silicone rubber, and featuring raised pips that echo the toe pads of a gecko, this wheel has excellent traction against a multitude of surfaces. The spoke design allows it to easily compress and conform around objects, and it''s non-directional: it will reliably provide the same results rotation after rotation, no matter what direction you spin it! The plastic center core features a 14mm bore…', 'goBILDA', null, true, 'https://www.gobilda.com/gripforce-gecko-wheel-14mm-bore-96mm-diameter-30a-durometer/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1460/images/15737/3613-0014-0096_REV2-_CAT__38432.1767737245.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Intake Wheels', 'gobilda'),
  ('GripForce Gecko™ Wheel (8mm REX® Bore, 32mm Diameter, 30A Durometer)', '3613-4008-0032', 'Grab the utmost of grippage with this 32mm Diameter Gripforce Gecko™ Wheel! Constructed of high-grip silicone rubber, and featuring raised pips that echo the toe pads of a gecko, this wheel has excellent traction against a multitude of surfaces. The spoke design allows it to easily compress and conform around objects, and it''s non-directional: it will reliably provide the same results rotation after rotation, no matter what direction you spin it! The 8mm REX® bore plastic center core provides…', 'goBILDA', null, true, 'https://www.gobilda.com/gripforce-gecko-wheel-8mm-rex-bore-32mm-diameter-30a-durometer/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2454/images/15462/3613-4008-0032_-_CAT__42351__54312.1762286655.386.513.jpg?c=1', 'MOTION / Wheels & Tires / GripForce Gecko™ Wheels', 'gobilda'),
  ('GripForce Gecko™ Wheel (8mm REX® Bore, 48mm Diameter, 30A Durometer)', '3613-4008-0048', 'Grab the utmost of grippage with this 48mm Diameter Gripforce Gecko™ Wheel! Constructed of high-grip silicone rubber, and featuring raised pips that echo the toe pads of a gecko, this wheel has excellent traction against a multitude of surfaces. The spoke design allows it to easily compress and conform around objects, and it''s non-directional: it will reliably provide the same results rotation after rotation, no matter what direction you spin it! The 8mm REX® bore plastic center core provides…', 'goBILDA', null, true, 'https://www.gobilda.com/gripforce-gecko-wheel-8mm-rex-bore-48mm-diameter-30a-durometer/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1642/images/15464/3613-4008-0048_-_CAT__25582.1762288998.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Intake Wheels', 'gobilda'),
  ('3614 Series Rhino Wheel (14mm Bore, 72mm Diameter, 30A Durometer)', '3614-0014-0072', 'These 72mm Diameter, 32mm wide Rhino Wheels are wrapped in 5mm of soft and grippy rubber. The rubber is Shore 30A which means it will have a consistency similar to that of a rubber band. Small bumps and pebbles on a smooth surface will not be noticed when running your chassis as the rubber of the wheel will conform right over them. The grippiness will yield excellent smooth surface traction.', 'goBILDA', null, true, 'https://www.gobilda.com/3614-series-rhino-wheel-14mm-bore-72mm-diameter-30a-durometer/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1599/images/8399/3614-0014-0072__74117__89322.1701993452.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Rhino Wheels', 'gobilda'),
  ('3614 Series Rhino Wheel (14mm Bore, 96mm Diameter, 30A Durometer)', '3614-0014-0096', 'These 96mm Diameter, 32mm wide Rhino Wheels are wrapped in 5mm of soft and grippy rubber. The rubber is Shore 30A which means it will have a consistency similar to that of a rubber band. Small bumps and pebbles on a smooth surface will not be noticed when running your chassis as the rubber of the wheel will conform right over them. The grippiness will yield excellent smooth surface traction.', 'goBILDA', null, true, 'https://www.gobilda.com/3614-series-rhino-wheel-14mm-bore-96mm-diameter-30a-durometer/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1592/images/8373/3614-0014-0096__21159__52700.1701993443.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Rhino Wheels', 'gobilda'),
  ('3615 Series Boot-Wheel (8mm REX® Bore, 48mm Diameter, 30A Durometer)', '3615-4008-0048', 'These Boot-Wheels are constructed of high-grip silicone rubber that offers excellent grip against a multitude of surfaces. The plastic center core gives this wheel great positive drive when installed on an 8mm REX® shaft, leaving only the axial constraint up to you. With The "toe" of your Boot-Wheels spinning towards your robot, they''ll give your items a little kick up; with the "heel" of the boot spinning towards your bot, they''ll give you a more horizontal trajectory. A combination of…', 'goBILDA', null, true, 'https://www.gobilda.com/3615-series-boot-wheel-8mm-rex-bore-48mm-diameter-30a-durometer/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1646/images/8619/3615-4008-0048__58325__95683.1701993525.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Intake Wheels', 'gobilda'),
  ('3615 Series Boot-Wheel (8mm REX® Bore, 72mm Diameter, 30A Durometer)', '3615-4008-0072', 'Boot-Wheels step up the possibilities of your intake assemblies! Made of high-grip silicone rubber offering excellent traction on a wide variety of surfaces, they also boast hexagonal cores for achieving positive drive on an 8mm REX® shaft. You can adjust the wheels'' orientations to generate fancy footwork: Turn their "toes" toward your robot to kick up the items they take in. Spin the "heels" of the boots towards your bot to impart a more horizontal trajectory. Combining these orientations…', 'goBILDA', null, true, 'https://www.gobilda.com/3615-series-boot-wheel-8mm-rex-bore-72mm-diameter-30a-durometer/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1765/images/9329/3615-4008-0072__68764__49115.1701993750.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Intake Wheels', 'gobilda'),
  ('3615 Series Boot-Wheel (8mm REX® Bore, 96mm Diameter, 30A Durometer)', '3615-4008-0096', 'Boot-Wheels step up the possibilities of your intake assemblies! Made of high-grip silicone rubber offering excellent traction on a wide variety of surfaces, they also boast hexagonal cores for achieving positive drive on an 8mm REX® shaft. You can adjust the wheels'' orientations to generate fancy footwork: Turn their "toes" toward your robot to kick up the items they take in. Spin the "heels" of the boots towards your bot to impart a more horizontal trajectory. Combining these orientations…', 'goBILDA', null, true, 'https://www.gobilda.com/3615-series-boot-wheel-8mm-rex-bore-96mm-diameter-30a-durometer/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/1799/images/9646/3615-4008-0096_Ang1__99363__63586.1701993852.386.513.jpg?c=1', 'MOTION / Wheels & Tires / Intake Wheels', 'gobilda'),
  ('Wasteland Wheel (144mm Diameter, 52mm Width)', '3616-0014-0144', 'The toughest of projects calls for the toughest of wheels! A futuristic tire-wheel fusion with an aggressive rubber tread, this 144mm Diameter Wasteland Wheel is ready for action on and off the road—whether you''re talking a rocky trail, hard pavement, or any world in between. Thriving in a wasteland requires adaptability as well as strength. That''s why the Wasteland Wheel''s tough plastic core is surrounded by a treaded rubber structure "filled" with airless non-pneumatic tire (NPT) cells that…', 'goBILDA', null, true, 'https://www.gobilda.com/wasteland-wheel-144mm-diameter-52mm-width/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2058/images/16118/3616-0014-0144_Ang2__00943.1771445132.386.513.jpg?c=1', 'MOTION / Wheels & Tires / All-Terrain Wheels & Tires', 'gobilda'),
  ('Wasteland Wheel (192mm Diameter, 72mm Width)', '3616-0014-0192', 'The toughest of projects calls for the toughest of wheels! A futuristic tire-wheel fusion with an aggressive rubber tread, this 192mm Diameter Wasteland Wheel is ready for action on and off the road—whether you''re talking a rocky trail, hard pavement, or any world in between. Thriving in a wasteland requires adaptability as well as strength. That''s why the Wasteland Wheel''s tough plastic core is surrounded by a treaded rubber structure "filled" with airless non-pneumatic tire (NPT) cells that…', 'goBILDA', null, true, 'https://www.gobilda.com/wasteland-wheel-192mm-diameter-72mm-width/', 'https://cdn11.bigcommerce.com/s-x56mtydx1w/products/2079/images/16108/3616-0014-0192_Ang2__98762.1771444339.386.513.jpg?c=1', 'MOTION / Wheels & Tires / All-Terrain Wheels & Tires', 'gobilda')
on conflict (btrim(manufacturer), btrim(sku))
